### C++代码

```cpp
#include <iostream>
#include <vector>
using namespace std;

const long long MOD = 1000000007;

int n;
vector<int> a;
vector<vector<int>> adj;
vector<long long> C, D; // C[u]: 以 u 为根且必包含 u 的连通块个数
                       // D[u]: 以 u 为根且必包含 u 的连通块中奇数权值节点数量之和

// DFS：递归计算每个节点的 C[u] 和 D[u]
void dfs(int u, int parent) {
    // 收集 u 的所有子节点（排除父节点）
    vector<int> children;
    for (int v : adj[u]) {
        if (v == parent) continue;
        dfs(v, u);
        children.push_back(v);
    }
    int m = children.size();
    long long prod = 1;
    // 计算 prod = ∏ (1 + C[v])，表示 u 子树所有子连通块的选择方式
    for (int i = 0; i < m; i++) {
        int v = children[i];
        prod = (prod * (C[v] + 1)) % MOD;
    }
    C[u] = prod; // u 为根的连通块总数

    // 计算前缀积和后缀积，方便求去掉某个子节点因子的乘积
    vector<long long> prefix(m + 1, 1), suffix(m + 1, 1);
    for (int i = 0; i < m; i++) {
        int v = children[i];
        prefix[i + 1] = (prefix[i] * (C[v] + 1)) % MOD;
    }
    for (int i = m - 1; i >= 0; i--) {
        int v = children[i];
        suffix[i] = (suffix[i + 1] * (C[v] + 1)) % MOD;
    }
    // f(u)=1 当 a[u] 为奇数，否则为0
    long long f = (a[u] % 2);
    // 节点 u 自身的贡献：f(u) * (∏ (1 + C[v]))
    long long sum = (f * prod) % MOD;
    // 累加各子树贡献：对于每个子节点 v，其贡献为 D[v] 乘以除去 v 的其他子节点的选择方式
    for (int i = 0; i < m; i++) {
        int v = children[i];
        long long rest = (prefix[i] * suffix[i + 1]) % MOD;
        sum = (sum + D[v] * rest) % MOD;
    }
    D[u] = sum;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    a.resize(n + 1);
    adj.resize(n + 1);
    C.resize(n + 1, 0);
    D.resize(n + 1, 0);
    for (int i = 1; i <= n; i++){
        cin >> a[i];
    }
    for (int i = 1; i <= n - 1; i++){
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    dfs(1, 0);
    long long ans = 0;
    // 将所有节点作为连通块的最低点时统计的 D[u] 累加即为答案
    for (int i = 1; i <= n; i++){
        ans = (ans + D[i]) % MOD;
    }
    cout << ans << "\n";
    return 0;
}
```


